public static int calculateEnergy(String s) {
    int energy = 0;
    int maxLength = 0;
    int currentLength = 0;

    for (int i = 0; i < s.length(); i++) {
        if (currentLength == 0) {
            maxLength = 1;
        } else if (s.charAt(i) == s.charAt(i - 1)) {
            currentLength++;
        } else {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 1;
        }
        energy = Math.max(energy, maxLength);
    }

    // Check the last segment of the string
    energy = Math.max(energy, currentLength);

    return energy;
}

